import{_ as e,c as o,s as i,o as d}from"./index-CgnHSxtd.js";const s={class:"aviso-container"},t={__name:"privacyPolicyView",setup(r){return(n,a)=>(d(),o("div",s,a[0]||(a[0]=[i('<h1 data-v-a60d853e>Aviso de Privacidad</h1><p data-v-a60d853e><strong data-v-a60d853e>Carpintería SOLO</strong> valora y respeta la privacidad de quienes nos contactan, por lo que la información personal que usted nos proporciona será tratada con confidencialidad y conforme a la normativa aplicable. </p><h2 data-v-a60d853e>1. Datos personales que se recaban</h2><p data-v-a60d853e>Podemos recabar los siguientes datos a través de nuestros formularios o vía WhatsApp:</p><ul data-v-a60d853e><li data-v-a60d853e>Nombre completo</li><li data-v-a60d853e>Empresa (opcional)</li><li data-v-a60d853e>Número telefónico</li><li data-v-a60d853e>Correo electrónico</li><li data-v-a60d853e>Mensaje o comentarios</li></ul><h2 data-v-a60d853e>2. Finalidades del tratamiento</h2><p data-v-a60d853e>Los datos recabados serán utilizados para:</p><ul data-v-a60d853e><li data-v-a60d853e>Brindar atención personalizada</li><li data-v-a60d853e>Responder dudas, solicitudes o cotizaciones</li><li data-v-a60d853e>Fines administrativos y de calidad</li></ul><h2 data-v-a60d853e>3. Transferencia de datos</h2><p data-v-a60d853e> No compartimos sus datos personales con terceros, salvo obligación legal o requerimiento de una autoridad competente. </p><h2 data-v-a60d853e>4. Uso de WhatsApp y formularios web</h2><p data-v-a60d853e> Al contactarnos por estos medios, usted autoriza el uso de sus datos conforme a este aviso de privacidad. </p><h2 data-v-a60d853e>5. Modificación y eliminación de datos</h2><p data-v-a60d853e> Usted puede solicitar en cualquier momento la modificación o eliminación de sus datos personales escribiéndonos a: <a href="mailto:carpinteriasolo@gmail.com" data-v-a60d853e>carpinteriasolo@gmail.com.</a></p><h2 data-v-a60d853e>6. Cambios al Aviso de Privacidad</h2><p data-v-a60d853e> Este aviso puede actualizarse sin previo aviso. Las versiones más recientes estarán disponibles en nuestro sitio web. </p><p class="fecha-actualizacion" data-v-a60d853e><strong data-v-a60d853e>Fecha de última actualización:</strong> Julio 2025 </p>',17)])))}},c=e(t,[["__scopeId","data-v-a60d853e"]]);export{c as default};
